BEGIN;SET LOCAL statement_timeout='8s';SET LOCAL lock_timeout='500ms';SET LOCAL search_path=pg_catalog;
DO $admit$ DECLARE c population_top3000_202608_202609_v1.acquisition_control%rowtype;p population_top3000_202608_202609_v1.pipeline_control%rowtype;v_bytes bigint;v_evidence jsonb;BEGIN
 IF NOT pg_try_advisory_xact_lock(2026083000261022) THEN RAISE EXCEPTION 'WAVE2_CONTROLLER_BUSY';END IF;
 SELECT * INTO c FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton FOR UPDATE;
 SELECT * INTO p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton FOR UPDATE;
 IF c.owner_id IS DISTINCT FROM 'top3000-recovery-20261023-root-4b1314bcb5c2' OR c.owner_fence IS DISTINCT FROM 2::bigint OR c.stop_generation IS DISTINCT FROM 0::bigint OR c.stopped IS DISTINCT FROM false OR c.enabled IS DISTINCT FROM true OR c.hold_reason IS NOT NULL OR c.admitted_until IS NULL OR c.admitted_until<=clock_timestamp() OR p.expected_owner_id IS DISTINCT FROM c.owner_id OR p.expected_owner_fence IS DISTINCT FROM c.owner_fence OR p.expected_stop_generation IS DISTINCT FROM c.stop_generation OR p.scope_sha256 IS DISTINCT FROM c.scope_sha256 OR c.scope_sha256 IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR p.deadline IS DISTINCT FROM '2026-10-25T22:36:17.687194Z'::timestamptz OR p.max_ticks<>3000 OR p.tick_count>3000 OR p.max_active_tasks<>1 THEN RAISE EXCEPTION 'WAVE2_OWNER_SCOPE_DEADLINE_OR_EXPECTED_BOUND_CHANGED';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) THEN RAISE EXCEPTION 'WAVE2_DRAIN_REQUIRED';END IF;
 IF p.budget_cap_usd<>250 OR p.actual_usd+p.accrued_usd+p.unavoidable_usd+p.remaining_uncommitted_usd+p.repair_egress_reserve_usd+p.reserved_request_usd>250 OR c.max_source_bytes<>250000000 OR (p.budget_evidence#>>'{resource_limits,max_relation_bytes}')::bigint<>4000000000 THEN RAISE EXCEPTION 'WAVE2_BUDGET_OR_STORAGE_BOUND_CHANGED';END IF;
 IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobid=596 AND database=current_database() AND btrim(command)='select population_top3000_202608_202609_v1.pipeline_tick_v1();') THEN RAISE EXCEPTION 'WAVE2_CRON_BINDING_CHANGED';END IF;
 SELECT coalesce(sum(pg_total_relation_size(r.oid)),0)::bigint INTO v_bytes FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND r.relkind IN('r','m');
 IF v_bytes>=4000000000 OR c.stored_bytes+c.reserved_bytes>250000000 THEN RAISE EXCEPTION 'WAVE2_RESOURCE_CEILING_ALREADY_EXHAUSTED';END IF;
 v_evidence:=jsonb_build_object('admission_id','retained-execution-wave2-20261023','reviewed_at',clock_timestamp(),'owner_id',c.owner_id,'owner_fence',c.owner_fence,'stop_generation',c.stop_generation,'prior_max_ticks',3000,'new_max_ticks',5000,'cumulative_ticks_at_review',p.tick_count,
 'allowed_work',jsonb_build_array('REF01 retained census/overview reconciliation: current-hash rollback then up to400 ticks','D02/S02 verified source-reference publication and reader delivery: current-hash rollback then404 useful executions','D03/D04/D05 retained shared features: current-hash numerical+actual26 rollback then first25 live series; expansion requires measured first25 resource review'),
 'future_daily_full_run_planning_ticks',1054,'planned_combined_ticks_with_ref01_review_allowance',1858,'remaining_tick_allowance',5000-p.tick_count,
 'resource_measurement',jsonb_build_object('mission_relation_bytes',v_bytes,'raw_source_bytes',c.stored_bytes,'provider_requests',c.provider_requests,'http_invocations',c.http_invocations),
 'resource_limits',jsonb_build_object('max_active_tasks',1,'max_relation_bytes',4000000000,'max_source_bytes',250000000,'ref01_new_relations_max_bytes',536870912,'daily_expansion_requires_actual_first25_review',true,'archive_reference_planning_bytes',5000000),
 'combined_worst_case_storage_exceeds_current_shared_cap',true,'storage_response','Do not reserve all family worst-case allowances simultaneously; measure actual first batches, preserve4GB guard and stop before expansion if projected fit is unsupported.',
 'provider_requests_admitted_by_this_extension',0,'new_http_invocations_admitted_by_this_extension',0,'new_subscription_or_capacity',false,'paid_model_calls',false,'new_monetary_encumbrance_usd',0,
 'budget_snapshot',jsonb_build_object('actual_usd',p.actual_usd,'accrued_usd',p.accrued_usd,'unavoidable_usd',p.unavoidable_usd,'reserved_request_usd',p.reserved_request_usd,'repair_egress_reserve_usd',p.repair_egress_reserve_usd,'remaining_uncommitted_usd',p.remaining_uncommitted_usd,'cap_usd',p.budget_cap_usd,'invoice_reconciled',false),
 'cost_basis','Database-only retained processing on unchanged existing capacity; existing10USD infrastructure and50USD repair/egress reserves retained. This does not assert invoice-confirmed zero cost.',
 'counters_and_failure_history_preserved',true,'admitted_until_unchanged',c.admitted_until,'original_deadline_unchanged',p.deadline,'review_condition','Current-hash actual tests before each registration; actual throughput/storage before daily expansion; no automatic allowance reset');
 UPDATE population_top3000_202608_202609_v1.pipeline_control SET max_ticks=5000,budget_verified_at=clock_timestamp(),budget_evidence=jsonb_set(budget_evidence,'{resource_limits,max_total_ticks}','5000'::jsonb)||jsonb_build_object('retained_execution_wave2',v_evidence) WHERE singleton;
 PERFORM cron.alter_job(596,active=>false);
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('FINITE_RETAINED_WORK_ALLOWANCE_RENEWED',v_evidence);
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ROOT_SCOPED_IMPLEMENTATION_ACTIVE',jsonb_build_object('operation_id','retained-wave2-runtime-gates-20261023','owner_id',c.owner_id,'owner_fence',c.owner_fence,'stop_generation',c.stop_generation,'cron_paused_for_actual_tests',true,'assigned_lanes',jsonb_build_array('REF01','D02/S02 archive publication','D03/D04/D05'),'no_competing_maintenance_writes',true,'next_checkpoint_required_by',clock_timestamp()+interval '15 minutes'));
END $admit$;
SELECT c.owner_id,c.owner_fence,p.tick_count,p.max_ticks,p.budget_cap_usd,p.unavoidable_usd,p.repair_egress_reserve_usd,p.remaining_uncommitted_usd,c.admitted_until,p.deadline,(SELECT active FROM cron.job WHERE jobid=596)cron_active FROM population_top3000_202608_202609_v1.acquisition_control c CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p;COMMIT;
